// Группируем заказы по адресу для оптимизации маршрута
const ordersByAddress = {};

for (const item of items) {
  const addr = item.json.delivery_address;
  if (!ordersByAddress[addr]) {
    ordersByAddress[addr] = [];
  }
  ordersByAddress[addr].push(item.json);
}

// Формируем сообщение
let message = "🚚 **ЗАДАНИЕ НА ДОСТАВКУ**\n";
message += `📅 Дата: ${new Date().toLocaleDateString('ru-RU')}\n`;
message += `📦 Всего заказов: ${items.length}\n\n`;

let orderNum = 1;
for (const [address, orders] of Object.entries(ordersByAddress)) {
  message += `📍 **Адрес: ${address}**\n`;
  for (const order of orders) {
    message += `├─ Заказ #${order.order_id.slice(0,8)}\n`;
    message += `│  Клиент: ${order.customer_name}\n`;
    message += `│  Телефон: ${order.customer_phone}\n`;
    message += `│  Товары: ${order.items_list}\n`;
    message += `│  Сумма: ${order.total_amount} руб.\n`;
    orderNum++;
  }
  message += `\n`;
}

return [{ json: { message } }];

